program='''def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            result.append((color, cells))
    return result


def _bounds(cells):
    return (min(r for r, c in cells), min(c for r, c in cells),
            max(r for r, c in cells), max(c for r, c in cells))


def _inside(cells, box):
    r0, c0, r1, c1 = box
    return all(r0 <= r <= r1 and c0 <= c <= c1 for r, c in cells)


def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return tuple(sorted((r - r0, c - c0) for r, c in cells))


def transform(grid):
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    objects = _components(grid)
    output = [row[:] for row in grid]

    for marker, marker_cells in objects:
        if marker == background:
            continue
        box = _bounds(marker_cells)
        templates = {
            _shape(cells)
            for color, cells in objects
            if color != background and color != marker and _inside(cells, box)
        }
        for color, cells in objects:
            if color == background or color == marker or _inside(cells, box):
                continue
            if _shape(cells) in templates:
                for r, c in cells:
                    output[r][c] = marker
    return output
'''
